-- Administrative role assignment without exposing auth.users directly.
create or replace function public.list_factory_users()returns table(user_id uuid,email text,roles text[])language plpgsql stable security definer set search_path=public,auth as $$begin if not public.has_factory_role(auth.uid(),array['admin'])then raise exception'not authorized';end if;return query select u.id,u.email::text,coalesce(array_agg(r.role_code order by r.role_code)filter(where r.role_code is not null),array[]::text[])from auth.users u left join public.factory_user_roles ur on ur.user_id=u.id left join public.factory_roles r using(factory_role_id)group by u.id,u.email order by u.email;end$$;
create or replace function public.assign_factory_user_role(p_user uuid,p_role text)returns uuid language plpgsql security definer set search_path=public as $$declare v_role uuid;begin if not has_factory_role(auth.uid(),array['admin'])then raise exception'not authorized';end if;select factory_role_id into v_role from factory_roles where role_code=p_role;if v_role is null then raise exception'unknown role';end if;insert into factory_user_roles(user_id,factory_role_id,created_by)values(p_user,v_role,auth.uid()::text)on conflict do nothing;insert into audit_log(user_id,action,entity_type,entity_id,new_value)values(auth.uid(),'Factory Role Assigned','factory_user_roles',p_user,jsonb_build_object('role',p_role));return p_user;end$$;
create or replace function public.remove_factory_user_role(p_user uuid,p_role text)returns uuid language plpgsql security definer set search_path=public as $$declare v_role uuid;begin if not has_factory_role(auth.uid(),array['admin'])then raise exception'not authorized';end if;if p_user=auth.uid()and p_role='admin'then raise exception'you cannot remove your own admin role';end if;select factory_role_id into v_role from factory_roles where role_code=p_role;if v_role is null then raise exception'unknown role';end if;delete from factory_user_roles where user_id=p_user and factory_role_id=v_role;insert into audit_log(user_id,action,entity_type,entity_id,old_value)values(auth.uid(),'Factory Role Removed','factory_user_roles',p_user,jsonb_build_object('role',p_role));return p_user;end$$;
revoke all on function public.list_factory_users()from public;revoke all on function public.assign_factory_user_role(uuid,text)from public;revoke all on function public.remove_factory_user_role(uuid,text)from public;
grant execute on function public.list_factory_users()to authenticated;grant execute on function public.assign_factory_user_role(uuid,text)to authenticated;grant execute on function public.remove_factory_user_role(uuid,text)to authenticated;
